simple.c:
int add(int a, int b) {
    return a + b;
}

simple.assembly:
// Function: add
// Prototype: int add(int, int)
//
// Arguments: a in W0, b in W1 (32-bit int maps to W registers)
// Return:    result in W0
//
// AAPCS64: W0-W7 are the lower 32 bits of X0-X7.
//          For int (32-bit), the upper 32 bits are irrelevant.

add:
    add     w0, w0, w1      // w0 = w0 + w1  (result in w0)
    ret                      // return to caller (branch to X30/LR)

// Prologue/epilogue: not needed — no callee-saved registers used,
// no local variables, no stack frame created.
// Total cost: 2 instructions.

complex.c:
struct Point {
    double x;
    double y;
};

struct Point translate(struct Point p, double dx, double dy) {
    p.x += dx;
    p.y += dy;
    return p;
}

complex.assembly:
// Function: translate
// Prototype: struct Point translate(struct Point, double, double)
//
// AAPCS64 struct rules:
//   - struct Point is 16 bytes (2 doubles)
//   - ≤ 16 bytes: passed in registers
//   - p.x in D0 (first FP register)
//   - p.y in D1 (second FP register)
//   - dx in D2, dy in D3
//   - Return value: struct ≤ 16 bytes in D0, D1
//
// Callee-saved: none needed (V8-V15 not used)
// Stack frame: not needed

translate:
    fadd    d0, d0, d2      // p.x = p.x + dx
    fadd    d1, d1, d3      // p.y = p.y + dy
    ret

// If the struct were > 16 bytes, e.g.:
// struct Large { double x, y, z, w; };  // 32 bytes
//
// Then it would be passed indirectly:
//   - Caller passes pointer to struct in X0
//   - Callee dereferences X0 to read fields
//   - Return: caller allocates space, passes pointer in X8
//
// Example for large struct return:
// large_translate:
//     ldr     d0, [x0]            // load p.x
//     ldr     d1, [x0, #8]        // load p.y
//     ldr     d2, [x0, #16]       // load p.z
//     ldr     d3, [x0, #24]       // load p.w
//     fadd    d0, d0, d4          // p.x + dx
//     fadd    d1, d1, d5          // p.y + dy
//     fadd    d2, d2, d6          // p.z + dz
//     fadd    d3, d3, d7          // p.w + dw
//     str     d0, [x8]            // store to caller-provided buffer
//     str     d1, [x8, #8]
//     str     d2, [x8, #16]
//     str     d3, [x8, #24]
//     mov     x0, x8              // return pointer in x0
//     ret
